\label{def:slope-stability}
The tower is slope stable if some $n_0\geq1$ satisfies, for all $n\geq n_0$,
\begin{equation}\label{eq:intro-strong-stability}
 S_n=
 \left(
 \bigsqcup_{j=0}^{p^{n-n_0}-1}
 \frac{j+(\{0\}\sqcup S_{n_0})}{p^{n-n_0}}
 \right)\setminus\{0\}.
\end{equation}
The final multiset operation removes one zero.  We also call this
strong slope stability to distinguish it from partial propagation.

\label{def:block-propagation}
For $1\leq b\leq p$, the first $b$ blocks are eventually stable if
\begin{equation}\label{eq:b-block-slopes}
 S_{n+1}\cap(0,b/p)
 =\bigsqcup_{j=0}^{b-1}\frac{j+S_n}{p}
 \ \sqcup\ \left\{\frac1p,\ldots,\frac{b-1}{p}\right\}
 \qquad(n\gg0).
\end{equation}
The final multiset is empty when $b=1$. The case $b=1$ is also called
complete first-block propagation.

\label{thm:KZ-stability}
Assume eventual minimal break ratios. Then the tower is slope stable
provided that
\begin{equation}\label{eq:intro-gap}
 \deg f_i\leq\delta p^i-C\qquad\text{for all sufficiently large }i,
\end{equation}
where
\begin{equation}\label{eq:KZ-gap-constant}
 C=\frac{a(p-1)(d-1)^2}{8}.
\end{equation}

\label{def:reduced-equation}
The tower is defined by the Artin--Schreier--Witt equation
\begin{equation}\label{eq:asw-equation}
 F(\mathbf y)-\mathbf y=f(X),
\end{equation}
where $F$ is Witt-vector Frobenius and $f$ has the reduced presentation
\begin{equation}\label{eq:general-witt}
 f=\sum_{i\geq0}p^i\sum_{\substack{\ell\geq1\\p\nmid\ell}}
       [a_{i,\ell}][X]^\ell,\qquad
 f_i(X)=\sum_{\substack{\ell\geq1\\p\nmid\ell}}a_{i,\ell}X^\ell
       \in\mathbf F_q[X],\qquad f_0\ne0.
\end{equation}
Here $[\cdot]$ denotes the Teichm\"uller lift, each $f_i$ is a
polynomial, and all displayed positive exponents are prime to $p$.

\label{prop:KW-formulas}
For our $\mathbf Z_p$-tower, with reduced defining Witt vector $f$,
\begin{equation}\label{eq:intro-break-formula}
 s_n=\max_{0\leq i<n}p^{n-1-i}\deg f_i,\qquad \deg0=-\infty,
\end{equation}
and
\begin{equation}\label{eq:intro-genus-formula}
 2g_n=\sum_{r=1}^n(p-1)p^{r-1}(s_r-1).
\end{equation}

\label{thm:KW-genus}
For our $\mathbf Z_p$-tower, with reduced defining Witt vector $f$, genus stability and ramification
stability are equivalent.  More explicitly,
\begin{equation}\label{eq:corrected-genus-criterion}
 \begin{split}
 \text{genus stability}
 &\ \Longleftrightarrow\
 s_n=\lambda p^{n-1}+\mu\quad(n\gg0)\\
 &\ \Longleftrightarrow\
 \max_{0\leq i<n}p^{n-1-i}\deg f_i
      =\lambda p^{n-1}+\mu\quad(n\gg0),
 \end{split}
\end{equation}
for fixed rational $\lambda>0$ and $\mu\leq0$.

\label{prop:attained-degree}
Our tower, with reduced defining Witt vector $f$, has eventual minimal
break ratios if and only if the normalized degrees $\deg f_i/p^i$
have a maximum. In that case, the maximum is attained at a unique
level $m$, and we write
\begin{equation}\label{eq:general-delta}
 \delta:=\max_{i\geq0}\frac{\deg f_i}{p^i}
        =\frac{\deg f_m}{p^m}.
\end{equation}

\label{def:ramification-parameters}
Retain $m$ and $\delta$ from Proposition~\ref{prop:attained-degree},
and put
\[
 d=\deg f_m,\qquad \delta=\frac d{p^m}.
\]
Since $f$ is reduced, $p\nmid d$.  For $n>m$, define the stable break
\begin{equation}\label{eq:general-D}
 D_n=\delta p^{n-1}=d p^{n-m-1}.
\end{equation}

\label{def:primitive-L}
Let $n\geq1$, and let $\chi_n:\mathbf Z_p\to\mathbf C_p^\times$ have exact order $p^n$. Its primitive
$L$-function is
\begin{equation}\label{eq:intro-primitive-L}
 L_f(\chi_n,s)=
 \prod_{x\in|\mathbf A^1_{\mathbf F_q}|}
 \left(1-\chi_n(\operatorname{Frob}_x)s^{\deg x}\right)^{-1}.
\end{equation}

\label{prop:zeta-primitive}
For every $n\geq1$,
\begin{equation}\label{eq:zeta-primitive}
 \begin{split}
 P(C_n,s)&=\prod_{r=1}^n\ \prod_{\operatorname{ord}(\chi)=p^r}
                         L_f(\chi,s),\\
 \frac{P(C_n,s)}{P(C_{n-1},s)}
          &=\prod_{\operatorname{ord}(\chi)=p^n}L_f(\chi,s).
 \end{split}
\end{equation}
Thus $Z(C_n,s)$ is the first product divided by $(1-s)(1-qs)$.

\label{prop:block-formulation}
Slope stability is equivalent to the following identity for every
sufficiently large $n$:
\begin{equation}\label{eq:adjacent-block-stability}
 S_{n+1}=
 \bigsqcup_{j=0}^{p-1}\frac{j+S_n}{p}
 \ \sqcup\ \left\{\frac1p,\frac2p,\ldots,\frac{p-1}{p}\right\}.
\end{equation}
All unions are multiset unions.  The $j$-th propagated block is
$(j+S_n)/p\subset(j/p,(j+1)/p)$; each displayed grid slope occurs once.

\label{prop:universal-reduction}
The Euler product $L_f(T,s)$ belongs to $1+s\mathbf Z_p[[T]][[s]]$.
The universal characteristic series satisfies
\begin{equation}\label{eq:universal-C}
 \begin{split}
 C_f^*(T,s)&=\prod_{t\geq0}L_f^*(T,q^ts)
             =\sum_{k\geq0}b_k(T)s^k,\\
 C_f^*(T,s)&=L_f^*(T,s)C_f^*(T,qs).
 \end{split}
\end{equation}
The product is interpreted coefficientwise in the $p$-adic
topology.  It belongs to $1+s\mathbf Z_p[[T]][[s]]$, specializes to
\eqref{eq:general-C}, and has reduction
\begin{equation}\label{eq:limit-Lstar}
 \overline{C_f^*(T,s)}
 =\overline{L_f^*(T,s)}
 =(1-s)\overline{L_f(T,s)}.
\end{equation}

\label{def:Artin-Hasse}
The Artin--Hasse exponential is the formal series
\begin{equation}\label{eq:AH}
 E(U)=\exp\left(\sum_{r\geq0}\frac{U^{p^r}}{p^r}\right)
 \in1+U\mathbf Q_p[[U]].
\end{equation}

\label{def:AH-parameters}
For $j\geq0$, define $\pi_j(T)\in T\mathbf Z_p[[T]]$ by
\begin{equation}\label{eq:pi-j}
 E(\pi_j(T))=(1+T)^{p^j}.
\end{equation}

\label{lem:pi-congruence}
For every $j\geq0$,
\begin{equation}\label{eq:pi-congruence}
 \pi_j(T)\equiv\pi_0(T)^{p^j}\pmod p.
\end{equation}
Since both series have zero constant term, this is equivalent to
\begin{equation}\label{eq:pi-error}
 \pi_j(T)-\pi_0(T)^{p^j}\in pT\mathbf Z_p[[T]].
\end{equation}
Thus the reduction of $\pi_j(T)$ has $T$-adic order $p^j$.

\label{lem:gauss-parameters}
For every $i\geq0$ and $u>0$,
\begin{equation}\label{eq:gauss-parameters}
 w_u\bigl(\pi_i(T)\bigr)=\min_{0\leq r\leq i}\{r+p^{i-r}u\}.
\end{equation}
In particular $w_u(\pi_i(T))\longrightarrow\infty$ as
$i\longrightarrow\infty$.

\label{def:splitting-function}
For the reduced defining Witt vector $f$, its splitting function is
\begin{equation}\label{eq:universal-splitting}
 F(T,X)=\prod_{i,\ell}E\bigl(\pi_i(T)[a_{i,\ell}]X^\ell\bigr)
       =\sum_{\nu\geq0}\eta_\nu(T)X^\nu,
 \qquad \eta_\nu(T)=0\quad(\nu<0).
\end{equation}
Here $\eta_\nu(T)\in\mathbf Z_q[[T]]$ is the coefficient of $X^\nu$.

\label{lem:splitting-identity}
For $t\in\mathbf F_{q^r}$,
\begin{equation}\label{eq:universal-splitting-character}
 \prod_{h=0}^{ar-1}F^{\sigma^h}(T,[t]^{p^h})
 =(1+T)^{\operatorname{Tr}_{W(\mathbf F_{q^r})/\mathbf Z_p}f(t)}.
\end{equation}
Superscripts $\sigma^h$ act on coefficients.

\label{thm:dwork-trace}
For a finite Witt truncation, the operator above satisfies
\begin{equation}\label{eq:dwork-trace}
 (q^r-1)\operatorname{Tr}((\Psi(T)^a)^r)
 =\sum_{t\in\mathbf F_{q^r}^{\times}}
 (1+T)^{\operatorname{Tr}_{W(\mathbf F_{q^r})/\mathbf Z_p}f(t)}
 \qquad(r\geq1).
\end{equation}

Consequently,
\begin{equation}\label{eq:general-Fredholm}
 C_f^*(T,s)=\det(1-s\Psi(T)^a)=\det(1-sM_q(T)).
\end{equation}

\label{lem:truncation-convergence}
For every $u>0$, each coefficient of $L_f(T,s)$ and $C_f^*(T,s)$ is the
$w_u$-limit of the corresponding coefficients for finite Witt truncations.

\label{prop:uniform-gauss}
For $C_f^*(T,s)=\sum_{k\geq0}b_k(T)s^k$ and every $u>0$,
\begin{equation}\label{eq:uniform-gauss}
 w_u(b_k(T))\geq a\sum_{j=0}^{k-1}\min\{\frac{(p-1)uj}{\delta},1\}.
\end{equation}

\label{prop:formal-nonmeromorphy}
Over $\mathbf F_p$, the tower
\[
 f=[X]+\sum_{\substack{\ell\geq2\\\ell\text{ prime}}}
                   p^\ell[X]^{p^\ell-1}
\]
has minimal break ratios, with $\delta=1$. Its $T$-adic $L$-function
is not meromorphic for the unreduced $T$-adic valuation, and its
characteristic series is not entire for that valuation.

\label{def:hodge-constants}
With the parameters in Definition~\ref{def:ramification-parameters}, define
\begin{equation}\label{eq:general-constants}
 h(k)=\frac{a(p-1)}{2\delta}k(k-1).
\end{equation}
We use the same quadratic expression for real arguments.
The degree-gap constant $C$ in \eqref{eq:KZ-gap-constant} also bounds the vertical distance
between the Hodge and contact polygons after division by $\delta$;
the bound is $C/\delta$.

\label{def:limiting-polygon}
Recall the universal characteristic series
$C_f^*(T,s)\in1+s\mathbf Z_p[[T]][[s]]$ of Section~\ref{sec:weight-space}.
A bar denotes coefficientwise reduction modulo $p$.  Define
\begin{equation}\label{eq:limit-polygon}
 N_\infty=\operatorname{NP}_T\!\left(\overline{C_f^*(T,s)}\right),
\end{equation}
where $\operatorname{ord}_T(T)=1$ on $\mathbf F_p((T))$.

\label{def:agreement-radius}
For a nonzero weight $T_0$ in the open unit disc, define
\begin{equation}\label{eq:weight-radius}
 R(T_0)=\sup\{R\geq0:N(T_0)|_{[0,R]}=N_\infty|_{[0,R]}\}
 \in[0,\infty].
\end{equation}
At a classical weight of conductor $p^n$, with $n>m$, put
\begin{equation}\label{eq:agreement-radius}
 R_n=R(\chi_n(1)-1)
 =\sup\{R\geq0:N_n|_{[0,R]}=N_\infty|_{[0,R]}\}.
\end{equation}
Thus $R_n=\infty$ precisely when $N_n=N_\infty$ on the entire half-line.

\label{prop:general-Hodge-contact}
Assume that the tower has eventual minimal break ratios, and let $r>m$.
The polygon $N_r$ lies above the Hodge polygon and below the contact
polygon.  Every contact is a vertex of $N_r$, and
\begin{equation}\label{eq:general-contact}
 h(k)\leq N_r(k)\leq h(k)+C/\delta\quad(k\in\mathbf Z_{\geq0}),\qquad
 N_r(k)=h(k)\quad(k\equiv0,1\pmod d).
\end{equation}

\label{prop:analytic-domain}
The series $C_f^*(T,s)$ is rigid analytic on
\begin{equation}\label{eq:analytic-domain}
 \{(T,s)\in\mathbf C_p^2:|T|_p<1,\ |s|_p<q\}.
\end{equation}
At every nontrivial classical weight $T=\chi_n(1)-1$, it is entire
as a function of $s$.  At $T=0$ it equals $1-s$.

\label{thm:annular-agreement}
Assume that the tower has eventual minimal break ratios, and let
$M\geq2$ satisfy $M\equiv0,1\pmod d$.
For every $T_0\in\mathbf C_p$ satisfying
\begin{equation}\label{eq:annular-contact-width}
 0<v_p(T_0)<\frac{\delta}{(p-1)(M-1)+C},
\end{equation}
we have
\begin{equation}\label{eq:annular-agreement}
 N(T_0)|_{[0,M]}=N_\infty|_{[0,M]}.
\end{equation}
The first $M$ slopes of the unnormalized polygon
$\operatorname{NP}_{v_p}C_f^*(T_0,s)$ are strictly less than $a$.
Equivalently, the corresponding slopes of $N(T_0)$ are less
than $a/v_p(T_0)$, so their zeros all belong to $|s|_p<q$.

\label{def:boundary-annulus}
For an integer $K\geq1$, put
\begin{equation}\label{eq:annulus-width}
 \varepsilon_K=
 \begin{cases}
 \displaystyle\frac{\delta}{(p-1)(K+d-2)+C},&d\geq2,\\[4pt]
 \displaystyle\frac{\delta}{(p-1)K},&d=1,
 \end{cases}\qquad
 \mathscr W_K=\{T\in\mathbf C_p:0<v_p(T)<\varepsilon_K\}.
\end{equation}
Thus $\mathscr W_K$ is the annulus
$p^{-\varepsilon_K}<|T|_p<1$, and $\varepsilon_K$ is its width
in the valuation coordinate.

\label{cor:annular-fixed-interval}
Assume eventual minimal break ratios.  For $0<c<1$, every weight satisfying
\begin{equation}\label{eq:fixed-interval-annulus}
 0<v_p(T)<\frac{\delta(1-c)}{C+(p-1)d}
\end{equation}
has the exact multiset identity
\begin{equation}\label{eq:fixed-interval-slopes}
 \operatorname{Slopes}_q C_f^*(T,s)\cap[0,c)
 =\left(\frac{v_p(T)}a\operatorname{Slopes}N_\infty\right)\cap[0,c).
\end{equation}

\label{thm:linear-stability}
Assume that the tower has eventual minimal break ratios, and let
\begin{equation}\label{eq:general-n-threshold}
 n>m,\qquad D_n>A.
\end{equation}
For every parameter $T_0\in\mathbf C_p$ satisfying
\begin{equation}\label{eq:classical-annulus}
 0<v_p(T_0)\leq\frac1{(p-1)p^{n-1}},
\end{equation}
the polygons $N(T_0)$ and $N_\infty$ agree on $[0,D_n-A]$.
In particular, for every $r\geq n$,
\begin{equation}\label{eq:linear-NP}
 N_r\big|_{[0,D_n-A]}=N_n\big|_{[0,D_n-A]}
 =N_\infty\big|_{[0,D_n-A]}.
\end{equation}
At the classical points this gives the exact multiset identity
\begin{equation}\label{eq:linear-slope-identity}
 S_r\cap\left(0,\frac{D_n-A}{D_r}\right)
 =\left(p^{n-r}S_n\right)\cap\left(0,\frac{D_n-A}{D_r}\right).
\end{equation}
Each side contains $D_n-A-1$ primitive slopes.

\label{rem:annulus-comparison}
A larger upper bound for $v_p(T_0)$ gives a larger
boundary annulus.  The four forms of the estimate are:
\begin{center}\small
\renewcommand{1.35}{1.65}
\begin{tabular}{@{}cll@{}}
\toprule
Condition & Upper bound for $v_p(T_0)$ & Guaranteed control\\
\midrule
\eqref{eq:annular-contact-width}
 & $\delta/[(p-1)(M-1)+C]$ & Through a contact $M$\\
\eqref{eq:annulus-width}
 & $\varepsilon_K$ of \eqref{eq:annulus-width} & Through $K+1$\\
\eqref{eq:fixed-interval-annulus}
 & $\delta(1-c)/[C+(p-1)d]$ & All $q$-slopes in $[0,c)$\\
\eqref{eq:classical-annulus}
 & $\delta/[(p-1)D_n]$ & Through $D_n-A$\\
\bottomrule
\end{tabular}
\end{center}
The first three bounds are strict; the last includes equality.
Equation~\eqref{eq:annular-contact-width} is the basic estimate.
The other three adapt it to an index, a slope interval, and a
classical level, respectively.

\label{cor:pointwise}
Let $N_\infty$ be the limit in Theorem~\ref{thm:limit-polygon}.
If the primitive slopes are listed increasingly as
$\alpha_{n,1},\ldots,\alpha_{n,D_n-1}$, then, for each fixed $j\geq1$,
\begin{equation}\label{eq:pointwise-slopes}
 p^{n-1}\alpha_{n,j}
 \quad\hbox{is independent of $n$ for all sufficiently large $n$.}
\end{equation}
It suffices that $n>m$ and $j+1\leq D_n-A$.
Also, for each fixed $0<c<1$, once
$n>m$ and $D_n>A/(1-c)$, every
$\alpha\in S_n\cap(0,c]$ propagates to
$\alpha/p^t\in S_{n+t}$ for every $t\geq0$, with the same multiplicity.
Here $c$ bounds the source slope at level $n$; at level $n+1$ the
descendant is at most $c/p<1/p$.

The $j$-th primitive slope is the slope of $N_n$ on $[j,j+1]$
divided by $a(p-1)p^{n-1}$.  Hence Corollary~\ref{thm:linear-stability}
gives the more explicit identity
\begin{equation}\label{eq:limit-indexed-slopes}
 a(p-1)p^{n-1}\alpha_{n,j}=N_\infty(j+1)-N_\infty(j)
 \qquad(j+1\leq D_n-A).
\end{equation}
This proves indexed stabilization.  For the assertion about a fixed $c$, $\alpha\leq c$
implies $\alpha<1-A/D_n$, so \eqref{eq:linear-slope-identity} applies
at every higher level.

\label{cor:four-descendants}
Let $n>m$ satisfy $D_n>A$.  A slope $\alpha\in S_n$ has the
following guaranteed descendants:
\begin{align}
 \alpha<1-A/D_n&\quad\Longrightarrow\quad \alpha/p\in S_{n+1},
       \label{eq:lower-branch}\\
 \alpha>A/D_n&\quad\Longrightarrow\quad (p-1+\alpha)/p\in S_{n+1}.
       \label{eq:upper-branch}
\end{align}
If $A/D_n<\alpha<1-A/D_n$, all four numbers
\begin{equation}\label{eq:four-descendants}
 \frac\alpha p,\quad \frac{1-\alpha}p,\quad
 1-\frac\alpha p,\quad 1-\frac{1-\alpha}p
\end{equation}
occur, each with the multiplicity of $\alpha$.  They are distinct unless
$\alpha=1/2$, when there are only two distinct values.  If $D_n>2A$,
every slope $\alpha\in S_n$ satisfies at least one of
\eqref{eq:lower-branch} and \eqref{eq:upper-branch}.

\label{cor:binary-descendants}
Let $n>m$ satisfy $D_n>A$, and let $\alpha\in S_n$ satisfy
$A/D_n<\alpha<1-A/D_n$.  At level $n+t$, for every $t\geq1$, all the
numbers
\begin{equation}\label{eq:binary-descendants}
 \frac{\beta+(p-1)\sum_{j=0}^{t-1}\eta_jp^j}{p^t},
 \qquad \beta\in\{\alpha,1-\alpha\},\quad \eta_j\in\{0,1\},
\end{equation}
occur with the multiplicity of $\alpha$.  There are $2^{t+1}$ distinct
values if $\alpha\ne1/2$, and $2^t$ if $\alpha=1/2$.

\label{cor:top-down}
Let $n>m$ satisfy $D_n>A$.  Every slope $\beta\in S_{n+1}$
in either of the following intervals has the displayed predecessor in
$S_n$, with exactly the same multiplicity:
\begin{equation}\label{eq:top-down}
 \begin{aligned}
 0<\beta<1/p-A/D_{n+1}
   &\quad\Longrightarrow\quad p\beta\in S_n,\\
 1-1/p+A/D_{n+1}<\beta<1
   &\quad\Longrightarrow\quad p\beta-(p-1)\in S_n.
 \end{aligned}
\end{equation}
Each of these outer bands contains $D_n-A-1$ slopes.  Thus their total
proportion among the $pD_n-1$ slopes at level $n+1$ tends to $2/p$.
Within each of $(0,1/p)$ and $(1-1/p,1)$, exactly $A$ slopes lie outside
the bands guaranteed by \eqref{eq:top-down}.
More generally, for every $t\geq1$,
\begin{equation}\label{eq:top-down-higher}
 \begin{aligned}
 0<\beta<p^{-t}-A/D_{n+t}
   &\ \Longrightarrow\ p^t\beta\in S_n,\\
 1-p^{-t}+A/D_{n+t}<\beta<1
   &\ \Longrightarrow\ p^t\beta-(p^t-1)\in S_n,
 \end{aligned}\qquad \beta\in S_{n+t}.
\end{equation}
Each of these two bands still contains exactly $D_n-A-1$ slopes,
and for fixed $t$ their combined proportion tends to $2/p^t$.

\label{prop:old-block-radius}
Complete first-block propagation is equivalent to $R_n\geq D_n+1$
for every sufficiently large $n$.

\label{prop:finite-block-stability}
Assume $n>m$ and $D_n\geq2$.
\begin{enumerate}[label=(\roman*),leftmargin=2em]
\item For an integer $1\leq b\leq p$, agreement
\begin{equation}\label{eq:b-block-agreement}
 N_{n+1}|_{[0,bD_n]}=N_n|_{[0,bD_n]}
\end{equation}
is equivalent to the multiset identity \eqref{eq:b-block-slopes}
at this level $n$, including the interior grid slopes.
\item The tower is slope stable if and only if, for every sufficiently
large $n$, \eqref{eq:b-block-agreement} holds with $b=p$.
\item In (ii), it is enough to use $b=\lceil p/2\rceil$.
\end{enumerate}

\label{lem:tail-estimate}
Write $b_k(f,\pi_{\chi_r})$ and $b_k(f^{<n},\pi_{\chi_r})$ for the
Fredholm coefficients evaluated at $T=\pi_{\chi_r}$; the additional
argument specifies the defining Witt vector.  For $r\geq n>m$ and $k\geq1$,
\begin{equation}\label{eq:tail-estimate}
 v_{\pi_{\chi_r}}\bigl(b_k(f,\pi_{\chi_r})-b_k(f^{<n},\pi_{\chi_r})\bigr)
 \geq h(k)+\frac{(p-1)(D_n-k+1)}{\delta}.
\end{equation}
In the reduced setting \eqref{eq:general-witt}, the stronger estimate
\begin{equation}\label{eq:strict-tail-estimate}
 v_{\pi_{\chi_r}}\bigl(b_k(f,\pi_{\chi_r})-b_k(f^{<n},\pi_{\chi_r})\bigr)
 \geq h(k)+\frac{(p-1)(D_n-k+1)}{\delta}+\frac1\delta
\end{equation}
also holds.  If the difference is zero, its valuation is $+\infty$.

\label{thm:all-slope-propagation}
Assume $p>2$ and that the tower has eventual minimal break ratios.
Suppose
\begin{equation}\label{eq:full-propagation-criterion}
 N_\infty(j)-h(j)\leq\frac{(p-1)j}{\delta}\qquad(j\geq1).
\end{equation}
It is enough to check this for the integers
\begin{equation}\label{eq:criterion-finite-range}
 1\leq j<A,
 \qquad A=d\left\lceil\frac{a(d-1)^2}{8d}\right\rceil.
\end{equation}
For all sufficiently large $n$ and every $t\geq1$, we then have
\begin{equation}\label{eq:all-slope-propagation}
 N_{n+t}\big|_{[0,D_n]}=N_n\big|_{[0,D_n]},\qquad
 S_{n+t}\cap(0,p^{-t})=(p^{-t}S_n)\cap(0,p^{-t}).
\end{equation}
Equivalently, $R_n\geq D_n+1$ for all sufficiently large $n$.
Thus every primitive slope propagates by division by $p$, with the
same multiplicity, from one common sufficiently large level onward.

\label{prop:classical-fiber}
For $n>m$ and $T_0=\chi_n(1)-1$, the fiber of $\mathscr X_f$
over $T_0$ has length $D_n$.  It consists of the zero $s=1$
and the zeros of $L_f(\chi_n,s)$, counted with multiplicity.
If a limiting slope $\lambda$ belongs to one of the finite
spectral pieces defined at $T_0$, its $q$-slope is
\begin{equation}\label{eq:spectral-classical-normalization}
 \frac{\lambda}{a(p-1)p^{n-1}}.
\end{equation}

\label{prop:Hodge-contact}
For every nontrivial finite character, $N_n$ lies above the
Hodge polygon and has contact vertices
\begin{equation}\label{eq:contact-points}
 (k,h(k))\qquad(k\equiv0,1\pmod{p+1}).
\end{equation}

\label{lem:contact-blocks}
At a contact index $k\equiv0,1\pmod{p+1}$, every square residue
block of the leading initial matrix is invertible over $\mathbf F_p$.

\label{lem:AH-recurrence}
For every integer $\nu$,
\begin{equation}\label{eq:AH-recurrence}
 \nu e_\nu=\sum_{h\geq0}e_{\nu-p^h}
 \quad\text{in }\mathbf F_p.
\end{equation}
Only finitely many terms on the right can be nonzero.

\label{prop:shift-register}
For every $j\geq1$,
\begin{equation}\label{eq:shift-register}
 \lambda_i^T \mathbf B_{i,j}\rho_i
 =\begin{cases}
 0,&j<i,\\
 2,&j=i,\\
 0,&j>i.
 \end{cases}
\end{equation}

\label{thm:detector}
For every $i,n\geq1$,
\begin{equation}\label{eq:detector-valuations}
 \begin{aligned}
 v_{\pi_{\chi_n}}\bigl(b_{K_i}(\pi_{\chi_n})\bigr)
   &=h(K_i)+\frac2{p+1} &&(n>i),\\
 v_{\pi_{\chi_n}}\bigl(b_{K_i}(\pi_{\chi_n})\bigr)
   &\geq h(K_i)+\frac4{p+1} &&(n\leq i).
 \end{aligned}
\end{equation}

\label{prop:vertex}
For every $i\geq1$:
\begin{enumerate}[label=\textup{(\roman*)}]
\item if $n>i$, then $(K_i,h(K_i)+\frac{2}{p+1})$ is a vertex of
$N_n$;
\item if $n\leq i$, then the Newton polygon at abscissa $K_i$ is strictly
above $h(K_i)+\frac{2}{p+1}$.
\end{enumerate}

Fix $i$ and a character $\chi_n$ of conductor $p^n$.  The Newton polygon
is the lower convex hull of the finite coefficient points
\[
 \bigl(k,v_{\pi_{\chi_n}}(b_k(\pi_{\chi_n}))\bigr),\qquad k\geq0;
\]
a zero coefficient has valuation $+\infty$ and supplies no finite point.
The polygon lies at or below every coefficient point.  Its vertices are
coefficient points, so their abscissas are integers.

\paragraph{Step 1: why the preceding contact vertex is enough.}
Proposition~\ref{prop:Hodge-contact} gives the Hodge bound
\[
 v_{\pi_{\chi_n}}(b_k(\pi_{\chi_n}))\geq h(k)
\]
for every $k$, and says that
\[
 \bigl(K_i-1,h(K_i-1)\bigr)
\]
is a vertex of the Newton polygon for every $n$.
There is also a later contact vertex at
$K_i+p-1=(p+1)(p^{i-1}+1)$.  Thus a next vertex after $K_i-1$ exists
and has a finite integer abscissa.  There is no integer strictly between
$K_i-1$ and $K_i$, so there are only two possibilities:
\begin{itemize}[leftmargin=*]
\item the next vertex has abscissa $K_i$, and the polygon there has
height $v_{\pi_{\chi_n}}(b_{K_i}(\pi_{\chi_n}))$;
\item the next vertex has abscissa $y\geq K_i+1$, and the polygon at
$K_i$ lies on the chord from the contact point at $K_i-1$ to that next
coefficient point.
\end{itemize}
In particular, if an edge passes across $K_i$, its left endpoint must be
the vertex at $K_i-1$.  An edge cannot skip an already established vertex.
It is therefore enough to estimate chords from this contact point to
future coefficient points.

\paragraph{Step 2: the height of every such chord.}
Let $y=K_i+\ell$ with $\ell\geq1$, and suppose $b_y(\pi_{\chi_n})\neq0$.
Applying \eqref{eq:chord-identity} with $x=K_i-1$ and $K=K_i$, the
chord joining the contact vertex $(K_i-1,h(K_i-1))$ to the Hodge
point $(y,h(y))$ has height
\[
 h(K_i)+\frac{p-1}{2(p+1)}\ell
\]
at $K_i$, because $K_i-x=1$ and $y-K_i=\ell$.
The actual coefficient point at $y$ is higher than or equal to the Hodge
point.  Raising the right endpoint of a chord by
$v_{\pi_{\chi_n}}(b_y(\pi_{\chi_n}))-h(y)$ raises its height at $K_i$ by
\[
 \frac{K_i-(K_i-1)}{y-(K_i-1)}
 \bigl(v_{\pi_{\chi_n}}(b_y(\pi_{\chi_n}))-h(y)\bigr)
 =\frac{v_{\pi_{\chi_n}}(b_y(\pi_{\chi_n}))-h(y)}{\ell+1}.
\]
This is linear interpolation along the chord. The chord from the same
left endpoint $(K_i-1,h(K_i-1))$ to the actual coefficient point
$(y,v_{\pi_{\chi_n}}(b_y(\pi_{\chi_n})))$ therefore satisfies the exact formula
\[
 \bigl[\text{chord height at }K_i\bigr]
 =h(K_i)+\frac{p-1}{2(p+1)}\ell
  +\frac{v_{\pi_{\chi_n}}(b_y(\pi_{\chi_n}))-h(y)}{\ell+1}.
\]
The last term is nonnegative, so
\begin{equation}\label{eq:future-chord-height}
 \bigl[\text{chord height at }K_i\bigr]
 \geq h(K_i)+\frac{p-1}{2(p+1)}\ell.
\end{equation}

For $p\geq7$, the inequality
$(p-1)\ell/(2(p+1))\geq3/(p+1)>2/(p+1)$ already makes every
such chord strictly higher than the active coefficient point.
For $p=5$ and $\ell\geq2$, the same bound gives an excess at least
$2/3>1/3$. It remains to treat $p=5$, $\ell=1$.

In this last case $K_i+1=6\cdot5^{i-1}+3$. Among the initial
indices $0,\ldots,K_i$, each of residues $0,1,2$ modulo six occurs
$5^{i-1}+1$ times, and each of residues $3,4,5$ occurs $5^{i-1}$
times. A leading entry is supported only when the column residue
is the negative of the row residue. The rows of residue one have
only $5^{i-1}$ possible column indices of residue five; likewise,
the rows of residue two have only $5^{i-1}$ possible column indices
of residue four. Each of these two disjoint rectangular blocks
has one more row than column. Their rank deficiencies force the
leading determinant to vanish.

Consequently the initial minor has valuation strictly greater than
$h(K_i+1)$. Contributions using a tail have positive excess, errors
in the Artin--Hasse parameters or integral coefficients have positive
excess, and every noninitial principal minor has excess at least
$4/6$. The Fredholm coefficient therefore satisfies
\[
 v_{\pi_{\chi_n}}\bigl(b_{K_i+1}(\pi_{\chi_n})\bigr)>h(K_i+1)
 \qquad(p=5),
\]
where a zero coefficient has valuation $+\infty$.
If this is a finite endpoint, the exact chord formula above now gives
\[
 \bigl[\text{chord height at }K_i\bigr]
 =h(K_i)+\frac13+
 \frac{v_{\pi_{\chi_n}}(b_{K_i+1}(\pi_{\chi_n}))-h(K_i+1)}2
 >h(K_i)+\frac13.
\]
Thus the strict chord comparison holds for every $p\geq5$.
